 String phase;void check(boolean b,String s){if(!b)throw new AssertionError(s);}@Override public void onCreate(Bundle b){super.onCreate(b);phase=b.getString("phase","upgrade");start();}
 @Override public void onStart(){Bundle out=new Bundle();try{runOnMainSync(new Runnable(){public void run(){}});Context c=getTargetContext();DurableCode.awaitReady();NotebookDisk disk=NotebookDisk.of(c);check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode==660001,"rebuilt version");NotebookDisk.Doc doc=disk.index.get(JavaMethodEditor.hash("web|https://example.com/libro"));check(doc!=null&&doc.chars>1300000&&doc.sha.equals(ProjectRuntime.digest(disk.file(doc))),"complete source survives "+phase);BananaEngine.Result answer=BananaEngine.run(c,"que es la hiperlemia",new ArrayList<String[]>(),"",true,OwnBrain.load(c));check(answer.text.contains("Olmo923")&&answer.text.contains("https://example.com/libro"),"indexed answer from retained source "+phase);check(disk.index.count()==3,"all documents retained "+phase);JSONObject learned=ModelDepot.report(c,"chat");check(learned!=null&&learned.optBoolean("readingWeights")&&learned.optBoolean("accepted"),"trained weights restored "+phase);check(ReadingTraining.portable(c).getJSONArray("done").length()==3,"training progress restored "+phase);check(!LearningLoop.enabled(c)&&LearningLoop.portable(c).getJSONArray("history").length()==1,"continuous pause and exercise history restored "+phase);if(phase.equals("fresh"))check(!ApkSigning.prefs(c).contains("sealed"),"private signing key absent");out.putString("stream","PASS NATIVE66_REOPEN "+phase+" complete source, checksum, index and attributed answer restored.\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
